package com.citacloud.app.views;
import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.FacturacionService; import com.vaadin.flow.component.button.*; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.BigDecimalField; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="pagos",layout=MainLayout.class) @PageTitle("Pagos | CitaCloud") @PermitAll public class PagosView extends VerticalLayout { private final FacturacionService service; private final UUID empresa; private final Grid<Pago> grid=new Grid<>(Pago.class,false);
 public PagosView(FacturacionService s){service=s;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);Button nuevo=new Button("Registrar pago",e->formulario());add(new HorizontalLayout(new H2("Pagos"),nuevo),new Paragraph("Registre pagos sin permitir montos superiores al saldo de la factura."));grid.addColumn(p->p.getFactura().getNumero()).setHeader("FACTURA");grid.addColumn(p->p.getFactura().getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(Pago::getFecha).setHeader("FECHA");grid.addColumn(Pago::getMonto).setHeader("MONTO");grid.addColumn(Pago::getMetodoPago).setHeader("MÉTODO");grid.setWidthFull();add(grid);cargar();} private void cargar(){grid.setItems(empresa==null?List.of():service.listarPagos(empresa));} private void formulario(){if(empresa==null)return;Dialog d=new Dialog();ComboBox<Factura> factura=new ComboBox<>("Factura",service.listar(empresa).stream().filter(f->f.getSaldo().signum()>0&&!"ANULADA".equals(f.getEstado())).toList());factura.setItemLabelGenerator(f->f.getNumero()+" · saldo "+f.getSaldo());BigDecimalField monto=new BigDecimalField("Monto");ComboBox<String> metodo=new ComboBox<>("Método",List.of("EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO"));TextField referencia=new TextField("Referencia");Button guardar=new Button("Registrar",e->{try{service.registrarPago(empresa,factura.getValue().getId(),monto.getValue(),metodo.getValue(),referencia.getValue());d.close();cargar();Notification.show("Pago registrado correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new VerticalLayout(factura,monto,metodo,referencia,guardar));d.open();}}
